{
  "candidates": [
    {
      "explanation": "Moderate pipeline-aware increase at node0 to rebuild inventory and reduce backlog, with node1 and node2 holding orders to avoid upstream backlog.",
      "rules": [
        {
          "when": "agent==0 and backlog>0 and pipeline<40",
          "delta": "min(4, backlog)"
        },
        {
          "when": "agent==0 and backlog>0 and pipeline>=40",
          "delta": "2"
        },
        {
          "when": "agent==1 and backlog==0 and inventory>10",
          "delta": "-2"
        },
        {
          "when": "agent==2 and backlog==0 and inventory>10",
          "delta": "-2"
        }
      ]
    },
    {
      "explanation": "Aggressive node0 increase to clear backlog and build inventory, while node1 and node2 reduce orders to prevent upstream backlog.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(6, backlog)"
        },
        {
          "when": "agent==0 and backlog==0 and inventory<5",
          "delta": "3"
        },
        {
          "when": "agent==1 and backlog==0 and inventory>5",
          "delta": "-3"
        },
        {
          "when": "agent==2 and backlog==0 and inventory>5",
          "delta": "-3"
        }
      ]
    },
    {
      "explanation": "Balanced response: node0 increases moderately, node1 and node2 adjust based on inventory and backlog to maintain service without overordering.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(4, backlog)"
        },
        {
          "when": "agent==0 and backlog==0 and inventory<10",
          "delta": "2"
        },
        {
          "when": "agent==1 and backlog>0",
          "delta": "2"
        },
        {
          "when": "agent==2 and backlog>0",
          "delta": "2"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Moderate pipeline-aware boost for all nodes to rebuild inventory and reduce backlog, with slightly larger boost for node0 to clear its high backlog. Corrections are small to avoid overordering.",
      "rules": [
        {
          "when": "agent == 0",
          "delta": "min(6, max(0, (backlog + 10) / 10))"
        },
        {
          "when": "agent == 1",
          "delta": "min(4, max(0, backlog / 5))"
        },
        {
          "when": "agent == 2",
          "delta": "min(3, max(0, backlog / 5))"
        }
      ]
    },
    {
      "explanation": "Aggressive boost for all nodes to quickly recover from emergency, with extra boost for node0 due to high backlog. Uses backlog and pipeline to scale correction.",
      "rules": [
        {
          "when": "agent == 0",
          "delta": "min(6, max(0, (backlog + 20) / 8))"
        },
        {
          "when": "agent == 1",
          "delta": "min(5, max(0, (backlog + 10) / 6))"
        },
        {
          "when": "agent == 2",
          "delta": "min(4, max(0, (backlog + 5) / 6))"
        }
      ]
    },
    {
      "explanation": "Conservative boost only when backlog is high, with priority to node0. Small corrections to avoid increasing upstream backlog.",
      "rules": [
        {
          "when": "agent == 0 and backlog > 50",
          "delta": "min(4, max(0, backlog / 15))"
        },
        {
          "when": "agent == 1 and backlog > 10",
          "delta": "min(3, max(0, backlog / 10))"
        },
        {
          "when": "agent == 2 and backlog > 5",
          "delta": "min(2, max(0, backlog / 10))"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Pipeline-aware relaxation: reduce orders when pipeline is high relative to recent demand, but boost if backlog is large. Node0 has huge backlog, so boost; nodes1 and2 have low backlog, so reduce to avoid over-ordering.",
      "rules": [
        {
          "when": "agent == 0 and backlog > 50",
          "delta": "min(6, max(0, backlog / 20 - pipeline / 20))"
        },
        {
          "when": "agent == 1 and backlog < 20 and pipeline > 40",
          "delta": "-2"
        },
        {
          "when": "agent == 2 and backlog < 20 and pipeline > 40",
          "delta": "-2"
        },
        {
          "when": "true",
          "delta": "0"
        }
      ]
    },
    {
      "explanation": "Coordinated correction: increase node0 order to clear backlog, but reduce node1 and node2 orders to prevent upstream backlog buildup. Uses growth to moderate.",
      "rules": [
        {
          "when": "agent == 0 and backlog > 0",
          "delta": "min(6, max(0, backlog / 10))"
        },
        {
          "when": "agent == 1 and backlog < 20 and pipeline > 40",
          "delta": "-3"
        },
        {
          "when": "agent == 2 and backlog < 20 and pipeline > 40",
          "delta": "-3"
        },
        {
          "when": "true",
          "delta": "0"
        }
      ]
    },
    {
      "explanation": "Backlog-driven: boost orders where backlog exists, but cap by pipeline to avoid over-ordering. Node0 gets largest boost, node1 moderate, node2 minimal.",
      "rules": [
        {
          "when": "agent == 0 and backlog > 0",
          "delta": "min(6, max(0, backlog / 15))"
        },
        {
          "when": "agent == 1 and backlog > 0",
          "delta": "min(4, max(0, backlog / 10))"
        },
        {
          "when": "agent == 2 and backlog > 0",
          "delta": "min(2, max(0, backlog / 10))"
        },
        {
          "when": "true",
          "delta": "0"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Modest increase at node0 to cover demand surge, with node1 and node2 holding steady to avoid upstream backlog. Node0 pipeline is low, so order up slightly.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(6, backlog)"
        },
        {
          "when": "agent==0 and inventory<5",
          "delta": "2"
        },
        {
          "when": "agent==1 and backlog>0",
          "delta": "min(4, backlog)"
        },
        {
          "when": "agent==2 and backlog>0",
          "delta": "min(2, backlog)"
        }
      ]
    },
    {
      "explanation": "Pipeline-aware relaxation: reduce orders when pipeline is high to prevent upstream backlog, but increase node0 if inventory is low and demand is stable.",
      "rules": [
        {
          "when": "agent==0 and inventory<4 and pipeline<10",
          "delta": "3"
        },
        {
          "when": "agent==1 and pipeline>15",
          "delta": "-2"
        },
        {
          "when": "agent==2 and inventory>30",
          "delta": "-1"
        },
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(5, backlog)"
        }
      ]
    },
    {
      "explanation": "Coordinated response: node0 orders more to meet potential surge, node1 orders slightly more to replenish, node2 reduces to avoid excess inventory. Uses growth to detect demand increase.",
      "rules": [
        {
          "when": "agent==0 and growth>1.1",
          "delta": "4"
        },
        {
          "when": "agent==0 and inventory<3",
          "delta": "2"
        },
        {
          "when": "agent==1 and backlog>0",
          "delta": "min(3, backlog)"
        },
        {
          "when": "agent==2 and inventory>40",
          "delta": "-2"
        }
      ]
    }
  ]
}
